
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_cf22d_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_cf22d", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([5.969876125909666e-01, 4.283599454129852e-01, 2.068345344461078e-01, -7.059360403183215e-02, -3.915586581466840e-01, -7.143338253753180e-01, -9.618648938984495e-01, -1.072594875506826e+00, -1.158909248361287e+00, -1.391733292430302e+00, -1.152467736335179e+00, -4.847482415124645e-01, -2.989545752962566e-01, -2.566663127586723e-01, -2.359288292928141e-01, -1.614531265493135e-01, -4.629577956527334e-02, -4.134596365908221e-04, 1.910127979127225e-04, 4.309176406191506e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


